"use client"
import React, { useState } from "react"
import { Send, Palette } from "lucide-react"
import { supabase } from "../lib/supabase"
import { sendTelegramNotification } from "../lib/telegram"

interface NoteFormProps {
  onClose: () => void;
}

const PRESET_COLORS = [
  "#fef08a", // Yellow
  "#fecdd3", // Pink
  "#bae6fd", // Blue
  "#bbf7d0", // Green
  "#e9d5ff", // Purple
];

export const NoteForm: React.FC<NoteFormProps> = ({ onClose }) => {
  const [content, setContent] = useState("")
  const [author, setAuthor] = useState("")
  const [color, setColor] = useState(PRESET_COLORS[0])
  const [isSubmitting, setIsSubmitting] = useState(false)

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!content.trim() || !supabase) return

    setIsSubmitting(true)
    try {
      const finalAuthor = author.trim() || "Anonymous"

      // 1. Save to Supabase
      const { error } = await supabase.from('notes').insert([
        {
          content: content.trim(),
          author: finalAuthor,
          color: color,
        }
      ])

      if (error) throw error

      // 2. Reset form and close modal immediately for better UX
      setContent("")
      setAuthor("")
      setColor(PRESET_COLORS[0])
      onClose()

      // 3. Send Telegram Notification in the background (fire and forget)
      sendTelegramNotification(content.trim(), finalAuthor).catch(console.error)
    } catch (error) {
      console.error("Error adding note: ", error)
      alert("Failed to add note. Please try again.")
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <div className="note-form-container note-card animate-fade-in" style={{ backgroundColor: color, position: 'relative', width: '100%', maxWidth: '500px', transform: 'rotate(0)' }}>
      <button 
        type="button" 
        onClick={onClose}
        style={{
          position: 'absolute',
          top: '0.5rem',
          right: '1rem',
          background: 'none',
          border: 'none',
          color: 'rgba(0,0,0,0.4)',
          cursor: 'pointer',
          fontSize: '1.5rem',
          lineHeight: 1
        }}
      >
        &times;
      </button>
      
      <h2 style={{ marginBottom: '0.5rem', textAlign: 'center', color: '#1e293b', fontFamily: 'inherit' }}>Write a Note</h2>
      
      {/* Color Picker */}
      <div style={{ display: 'flex', justifyContent: 'center', gap: '0.5rem', marginBottom: '1.5rem', alignItems: 'center' }}>
        {PRESET_COLORS.map(preset => (
          <button
            key={preset}
            type="button"
            onClick={() => setColor(preset)}
            style={{
              width: '24px',
              height: '24px',
              borderRadius: '50%',
              backgroundColor: preset,
              border: color === preset ? '2px solid #334155' : '1px solid rgba(0,0,0,0.1)',
              cursor: 'pointer',
              padding: 0,
              boxShadow: color === preset ? '0 0 5px rgba(0,0,0,0.2)' : 'none'
            }}
            aria-label={`Select color ${preset}`}
          />
        ))}
        <div style={{ display: 'flex', alignItems: 'center', position: 'relative' }}>
          <input
            type="color"
            value={color}
            onChange={(e) => setColor(e.target.value)}
            style={{
              opacity: 0,
              position: 'absolute',
              width: '100%',
              height: '100%',
              cursor: 'pointer'
            }}
            title="Choose custom color"
          />
          <button
            type="button"
            style={{
              width: '24px',
              height: '24px',
              borderRadius: '50%',
              background: 'linear-gradient(45deg, red, orange, yellow, green, blue, indigo, violet)',
              border: !PRESET_COLORS.includes(color) ? '2px solid #334155' : '1px solid rgba(0,0,0,0.1)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              color: 'white',
              pointerEvents: 'none'
            }}
          >
            {!PRESET_COLORS.includes(color) && <Palette size={12} />}
          </button>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="note-form">
        <div className="input-group">
          <textarea
            id="content"
            className="sticky-input"
            placeholder="Write something nice..."
            value={content}
            onChange={(e) => setContent(e.target.value)}
            required
            maxLength={500}
          />
        </div>

        <div className="input-group" style={{ marginTop: '0.5rem' }}>
          <input
            id="author"
            type="text"
            className="sticky-input"
            placeholder="- Your Name (or Nickname)"
            value={author}
            onChange={(e) => setAuthor(e.target.value)}
            maxLength={30}
          />
        </div>

        <button
          type="submit"
          className="btn-primary"
          disabled={isSubmitting || !content.trim()}
        >
          {isSubmitting ? (
            "Posting..."
          ) : (
            <>
              Stick it on the Wall <Send size={18} />
            </>
          )}
        </button>
      </form>
    </div>
  )
}
